+#!/usr/bin/env python3
+"""Check inertial cone placement, finite support and wind-boundary coupling."""
+from pathlib import Path
+import csv,json,subprocess
+ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'solver/cme_cpu/tests'
+
+def main():
+    OUT.mkdir(exist_ok=True)
+    columns=['start_day','end_day','lon_rad','lat_rad','halfwidth_rad','speed_kms','density_factor','temperature_factor']
+    configs=[]
+    for name,rows in [('single',[[0,1,0,0,.4,600,4,1]]),('overlap',[[0,1,0,0,.4,600,4,1],[0,1,0,0,.4,800,6,1]])]:
+        path=OUT/(name+'.csv')
+        with path.open('w',newline='') as f:w=csv.writer(f);w.writerow(columns);w.writerows(rows)
+        cfg=OUT/(name+'.cfg');cfg.write_text(f'cme_boundary_csv={path}\nnr=3\nntheta=2\nnphi=4\nrmin_au=.1\nrmax_au=.3\ntemperature_K=1000000\noutput_dir={OUT/name}\n')
+        configs.append(cfg)
+    source=OUT/'verify.cpp';source.write_text(r'''#define main solver_program_main
+#include "../mhd_solver_cme.cpp"
+#undef main
+int main(int argc,char**argv){try{
+ auto require=[](bool ok,const char*s){if(!ok)throw std::runtime_error(s);};
+ Config c(argv[1]);Solver s(c);A bg=s.initial(-1,.1,PI/2,0,false),a=s.initial(.5,.1,PI/2,0,false);
+ require(std::abs(a[0]/bg[0]-4)<1e-12,"Peak density enhancement");
+ require(std::abs(a[1]*VUNIT/1000-600)<1e-10,"Peak speed");
+ require(std::abs(a[5]-bg[5])<1e-14,"Unchanged normal B");
+ require(std::abs(a[1]*a[6]-bg[1]*bg[6])<1e-14,"Parker electric field invariant");
+ auto tail=s.initial(1.1,.1,PI/2,0,false),outside=s.initial(.5,.1,PI/2,.5,false),seam=s.initial(.5,.1,PI/2,2*PI,false);
+ require(tail==bg,"Finite temporal support");require(outside[0]==bg[0],"Finite angular support");
+ require(std::abs(seam[0]-a[0])<1e-12,"Periodic inertial longitude");
+ auto edge=s.initial(.5,.1,PI/2,.38,false);
+ require(std::abs(edge[0]/bg[0]-2.5)<1e-12,"Smooth half-weight angular edge");
+ Config c2(argv[2]);Solver s2(c2);auto overlap=s2.initial(.5,.1,PI/2,0,false);
+ require(std::abs(overlap[0]/bg[0]-6)<1e-12,"Overlapping density is not multiplied");
+ require(std::abs(overlap[1]*VUNIT/1000-800)<1e-10,"Later envelope wins ties");
+ std::cout<<"{\"finite_support\":true,\"inertial_angular_location\":true,\"peak_density_and_speed\":true,\"Parker_E_preserved\":true,\"smooth_edges\":true,\"overlap_rule\":true}\n";
+ return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}''')
+    executable=OUT/'verify';subprocess.run(['g++','-O2','-std=c++17','-fopenmp',str(source),'-o',str(executable)],check=True)
+    report=json.loads(subprocess.check_output([str(executable)]+[str(p) for p in configs],text=True))
+    (OUT/'verification.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2))
+
+if __name__=='__main__':main()
*** End Patch"));
